    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = applyVoucher(inv, { code: 'SUMMER2026', amount: 5000 });
  const withVoucher = r2.value;

  const totals = invoiceTotals(withVoucher);
  // Base: 42500 - 2125 discount + 8479 VAT = 48854
  // With voucher: 48854 - 5000 = 43854
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, voucher: 5000, total: 43854 });
});

