  const r2 = applyVoucher(inv, { code: 'HUGE', amount: 100000 });
  const withVoucher = r2.value;

  const totals = invoiceTotals(withVoucher);
  // Base: 48854, voucher: 100000 → total clamped to 0
  assert.equal(totals.total, 0);
});

