test('createInvoice calculates correct totals with tier discount', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  assert.equal(r.ok, true);
  const inv = r.value;
  const totals = invoiceTotals(inv);
  // 5 × 8500 = 42500, 5% tier discount = 2125
  // amount after discount = 40375, 21% VAT = 8478.75 → 8479
  assert.deepEqual(totals, { subtotal: 42500, discount: 2125, vat: 8479, total: 48854 });
});

test('invoiceTotals calculates VAT on amount after discount', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2026-10-07',
    status: 'draft',
    lines: [{ sku: 'DES-HOUR', name: 'Design work (hour)', qty: 10, unitPrice: 1000, vatRate: 21, discountPercent: 10 }],
  };
  const totals = invoiceTotals(invoice);
  // lineAmount = 10000, discount = 1000, afterDiscount = 9000, vat = 9000 * 21 / 100 = 1890
  assert.deepEqual(totals, { subtotal: 10000, discount: 1000, vat: 1890, voucher: 0, total: 10890 });
});

test('invoiceTotals handles lines with different VAT rates', () => {
