test('applyVoucher voucher is applied after VAT', () => {
  const r = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = applyVoucher(inv, { code: 'NEWCUSTOMER', amount: 10000 });
  const withVoucher = r2.value;

  const totals = invoiceTotals(withVoucher);
  // Standard tier (no discount): 42500 + 8925 VAT = 51425
  // With 10000 voucher: 51425 - 10000 = 41425
  assert.deepEqual(totals, { subtotal: 42500, discount: 0, vat: 8925, voucher: 10000, total: 41425 });
});

