test('applyVoucher works with various voucher amounts', () => {
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv = r.value;

  const r2 = applyVoucher(inv, { code: 'TINY', amount: 1 });
  assert.equal(r2.ok, true);
